    try { const resp = await route.fetch(); const h = Object.assign({}, resp.headers(), {'Access-Control-Allow-Origin':'*','Access-Control-Allow-Headers':'*','Access-Control-Allow-Methods':'GET, POST, OPTIONS'}); await route.fulfill({response: resp, headers: h}); } catch (e) { await route.abort(); }
  });
  const res = {};
  await bp.goto('http://10.17.1.66:3001/en', {waitUntil:'domcontentloaded'});
  await bp.waitForTimeout(3000);
  await bp.getByText('Log in', {exact:true}).first().click();
  await bp.waitForTimeout(2000);
